import{_ as o,C as e,c as r,o as a,aj as s,G as t,w as u}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Routines – During Session","description":"","frontmatter":{"outline":"deep","prev":{"text":"Routines – Pre-Session","link":"/trading-with-pav/routines-pre-session"},"next":{"text":"Routines – Post-Session","link":"/trading-with-pav/routines-post-session"}},"headers":[],"relativePath":"trading-with-pav/routines-during-session.md","filePath":"trading-with-pav/routines-during-session.md"}'),d={name:"trading-with-pav/routines-during-session.md"};function h(c,i,p,m,g,f){const l=e("GraphComment"),n=e("ClientOnly");return a(),r("div",null,[i[0]||(i[0]=s('<h1 id="routines-–-during-session" tabindex="-1">Routines – During Session <a class="header-anchor" href="#routines-–-during-session" aria-label="Permalink to &quot;Routines – During Session&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#routines-–-during-session-1">Routines – During Session</a><ul><li><a href="#maintain-a-positive-and-focused-mindset">Maintain a Positive and Focused Mindset</a></li><li><a href="#recovery-significant-loss-or-negative-emotions">Recovery (Significant Loss or Negative Emotions)</a></li><li><a href="#monitor-throughout-the-session">Monitor Throughout the Session</a></li><li><a href="#ongoing-analysis">Ongoing Analysis</a></li><li><a href="#trading">Trading</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="routines-–-during-session-1" tabindex="-1">Routines – During Session <a class="header-anchor" href="#routines-–-during-session-1" aria-label="Permalink to &quot;Routines – During Session&quot;">​</a></h2><h3 id="maintain-a-positive-and-focused-mindset" tabindex="-1">Maintain a Positive and Focused Mindset <a class="header-anchor" href="#maintain-a-positive-and-focused-mindset" aria-label="Permalink to &quot;Maintain a Positive and Focused Mindset&quot;">​</a></h3><ul><li><ol><li>Whenever focus has been distracted or minor stress is observed</li></ol><ul><li>a) Log nature of distraction</li><li>b) Office environment – quiet and serene</li><li>c) Sitting – back straight</li><li>d) Quick Relaxation / Breathing session</li><li>e) FOCUS</li></ul></li><li><ol start="2"><li>Once per hour</li></ol><ul><li>a) Conduct one or two Chi Gung forms</li><li>b) Quick Relaxation / Breathing session</li><li>c) FOCUS</li></ul></li><li><ol start="3"><li>Mid-Session Break (if conducting full session)</li></ol><ul><li>a) Eat a small meal</li><li>b) Full Relaxation / Breathing session</li><li>c) Reflect on the opportunities that the trading day brings</li><li>d) FOCUS</li></ul></li></ul><h3 id="recovery-significant-loss-or-negative-emotions" tabindex="-1">Recovery (Significant Loss or Negative Emotions) <a class="header-anchor" href="#recovery-significant-loss-or-negative-emotions" aria-label="Permalink to &quot;Recovery (Significant Loss or Negative Emotions)&quot;">​</a></h3><ul><li><ol><li>Relaxation – Body &amp; Mind</li></ol><ul><li>a) Relaxation / Breathing session</li><li>b) Conduct a short Chi Gung session.</li></ul></li><li><ol start="2"><li>Review</li></ol><ul><li>a) Consider the nature of the occurrence from the perspective of feelings</li><li>b) What feelings led to the decisions that were made, or actions that were taken?</li><li>c) How does this make me feel after the event? <ul><li>i) The key here is to explore my feelings in a non-judgmental manner. Accept them.</li></ul></li><li>d) What does this mean? Where is the lesson?</li><li>e) How will I behave in future when encountering the same circumstances?</li><li>f) Visually replay the situation with the new improved behavior. Confirm improved feelings.</li></ul></li><li><ol start="3"><li>Release</li></ol><ul><li>a) Relaxation / Breathing session</li><li>b) Forgive</li><li>c) Completely let go of whatever happened.</li><li>d) Review motivation journal.</li></ul></li></ul><h3 id="monitor-throughout-the-session" tabindex="-1">Monitor Throughout the Session <a class="header-anchor" href="#monitor-throughout-the-session" aria-label="Permalink to &quot;Monitor Throughout the Session&quot;">​</a></h3><ul><li><ol><li>Regular monitoring</li></ol><ul><li>a) Throughout the session, take time to monitor and record any significant observations regarding: <ul><li>i) Market structure and price action movement</li><li>ii) My trading process</li><li>iii) My physical and psychological state</li></ul></li></ul></li><li><ol start="2"><li>When?</li></ol><ul><li>a) At key session times: <ul><li>i) Pre-Session, Mid-Session, Post-Session</li></ul></li><li>b) At key events <ul><li>i) After exiting every trade</li><li>ii) After any structural changes</li></ul></li><li>c) Any other time that I feel I’ve gained an insight into market structure, my trading process or my physical and psychological state.</li></ul></li></ul><h3 id="ongoing-analysis" tabindex="-1">Ongoing Analysis <a class="header-anchor" href="#ongoing-analysis" aria-label="Permalink to &quot;Ongoing Analysis&quot;">​</a></h3><ul><li><ol><li>Determine Candle Pattern Sentiment</li></ol><ul><li>a) Classify the candle pattern and determine the short-term sentiment of price.</li><li>b) Classify the candle pattern <ul><li>i) High / Mid / Low Close</li><li>ii) Bull / Range / Bear Candle</li></ul></li><li>c) Determine the sentiment of the pattern</li></ul></li><li><ol start="2"><li>Consider the Context</li></ol><ul><li>a) Every pattern is unique and MUST be considered in the context of the background market environment in which it occurs.</li><li>b) Where is the current price action in relation to key market structure features: <ul><li>i) Support or Resistance</li><li>ii) Trend</li><li>iii) Swing Highs and Lows</li></ul></li><li>c) What does this mean with respect to the sentiment of the pattern and the potential future price action?</li></ul></li><li><ol start="3"><li>Does it Support my Premise?</li></ol><ul><li>a) Is the market action continuing as expected, or is something indicating we’re out of sync with market flow? Does the current price action and sentiment support our previous expectations for future price action? <ul><li>i) Yes <ul><li>(1) Await further price information.</li></ul></li><li>ii) No <ul><li>(1) Decide whether to hold for the next candle, or to reconsider the Initial Market Analysis.</li></ul></li><li>iii) Unsure <ul><li>(1) Wait for further price information.</li></ul></li></ul></li></ul></li><li><ol start="4"><li>Repeat</li></ol><ul><li>a) Repeat the process as new information appears on the chart.</li></ul></li></ul><h3 id="trading" tabindex="-1">Trading <a class="header-anchor" href="#trading" aria-label="Permalink to &quot;Trading&quot;">​</a></h3><ul><li><ol><li>Trade Preparation</li></ol><ul><li>a) Monitor price movement confirming it matches the behaviour previously anticipated. If price action differs from expectations, return to the initial analysis and recheck premise and assumptions.</li><li>b) Identify trade parameters <ul><li>i) Stop loss location</li><li>ii) Targets T1 &amp; T2</li><li>iii) Confirm entry zone <ul><li>(1) Consider both LWP (if identified) and LRP</li></ul></li></ul></li><li>c) Identify preferred entry plan <ul><li>i) Stop and/or limit order</li></ul></li><li>d) Final confirmation <ul><li>i) The setup and trade is valid for this market environment</li><li>ii) Price action is supporting the trade premise.</li></ul></li></ul></li><li><ol start="2"><li>Trade Entry</li></ol><ul><li>a) Monitor price movement bar by bar, until the entry locations are identified. Ensure price continues to support the trade premise. <ul><li>i) Determine candle pattern sentiment</li><li>ii) Consider the context</li><li>iii) Does it support my premise</li></ul></li><li>b) If bracketing price, place a stop entry order at the LWP as soon as it‟s identified.</li><li>c) If working an entry, place an appropriate order in the market as soon as the entry decision is made. <ul><li>i) Limit entry order in area of stall</li><li>ii) Limit or Stop entry order on price action trigger.</li></ul></li><li>d) Confirm pending order details are correct. <ul><li>i) Entry price, direction, size,</li><li>ii) Contingent stop and target orders</li></ul></li><li>e) On fill: <ul><li>i) Cancel other no longer required pending orders.</li><li>ii) Confirm full or partial position filled</li></ul></li><li>f) Post-fill confirmation (gross error check) <ul><li>i) How do I feel about the entry?</li><li>ii) Confirm the setup and trade are valid for this market environment</li><li>iii) Confirm the price action is supporting the trade premise.</li></ul></li></ul></li><li><ol start="3"><li>Trade Management &amp; Exit</li></ol><ul><li>a) Continue monitoring price movement bar by bar. Ensure price continues to support the trade premise. <ul><li>i) Determine candle pattern sentiment</li><li>ii) Consider the context</li><li>iii) Does it support my premise</li></ul></li><li>b) Part One <ul><li>i) While premise remains valid: <ul><li>(1) Move the stop to breakeven when we would no longer wish to be in the trade if price retraced to the entry point.</li><li>(2) Move the stop to new levels where we would no longer wish to be in the trade if price retraced to that point.</li></ul></li><li>ii) When premise is threatened <ul><li>(1) Cancel position if immediate exit is required.</li><li>(2) Else work an exit through tightening both the stop and target orders, based upon lower timeframe price action.</li></ul></li></ul></li><li>c) Part Two <ul><li>i) While premise remains valid: <ul><li>(1) Move the stop to breakeven when we would no longer wish to be in part two if price retraced to the entry point.</li><li>(2) Move the stop to new levels where we would no longer wish to be in part two if price retraced to that point.</li></ul></li><li>ii) When premise is threatened <ul><li>(1) Cancel position if immediate exit is required.</li><li>(2) Else work an exit through tightening both the stop and target orders, based upon lower timeframe price action.</li></ul></li><li>iii) When market shows increased strength <ul><li>(1) Consider extension of T2 or replacement with a trailing stop.</li></ul></li></ul></li><li>d) On partial exit <ul><li>i) Confirm order correctly filled.</li></ul></li><li>e) On total exit <ul><li>i) Confirm flat.</li></ul></li></ul></li><li><ol start="4"><li>Post-Trade</li></ol><ul><li>a) Reconfigure order entry screens or DOM.</li><li>b) In the event of a loss: <ul><li>i) Consider the need for a recovery process.</li></ul></li><li>c) Is price setting up for a possible re-entry or subsequent setup? <ul><li>i) Delay any trade log entries and prepare for the new trading process.</li></ul></li><li>d) When time permits: <ul><li>i) Update trade log.</li><li>ii) Monitor and record significant observations: <ul><li>(1) Market structure or price action.</li><li>(2) My trading process.</li><li>(3) My physical and psychological state.</li></ul></li></ul></li></ul></li></ul><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',14)),t(n,null,{default:u(()=>[t(l)]),_:1})])}const b=o(d,[["render",h]]);export{y as __pageData,b as default};
